(6991531, 1056110, 81362, '<td valign="top">Enjoying the sense of gesture.</td>', 'Enjoying the sense of gesture.', '2013-03-04 21:54:13.000000', NULL, 1),
(6991534, 1056357, 124982, '<td valign="top">Nice composition, just a little flat on the lighting. No shadows etc.</td>', 'Nice composition, just a little flat on the lighting. No shadows etc.', '2013-03-04 21:56:03.000000', NULL, 1),
(6991535, 1056257, 124982, '<td valign="top">Very cute, and nicely captured!</td>', 'Very cute, and nicely captured!', '2013-03-04 21:56:13.000000', NULL, 1),
(6991537, 1056414, 124982, '<td valign="top">Very curious to know how you managed to capture a hummingbird on white background! Great image!</td>', 'Very curious to know how you managed to capture a hummingbird on white background! Great image!', '2013-03-04 21:56:53.000000', NULL, 1),
(6991539, 1055227, 124982, '<td valign="top">Very peaceful.A slight pinkish hue to the image is quite attractive!</td>', 'Very peaceful.A slight pinkish hue to the image is quite attractive!', '2013-03-04 21:57:17.000000', NULL, 1),
(6991540, 1056259, 124982, '<td valign="top">Lovely detail and depth of focus!</td>', 'Lovely detail and depth of focus!', '2013-03-04 21:57:36.000000', NULL, 1),
(6991541, 1056430, 124982, '<td valign="top">Simple. Elegant. Well seen!</td>', 'Simple. Elegant. Well seen!', '2013-03-04 21:57:55.000000', NULL, 1),
(6991542, 1056381, 124982, '<td valign="top">Simple and effective! Nice catchlights!</td>', 'Simple and effective! Nice catchlights!', '2013-03-04 21:58:20.000000', NULL, 1),
(6991544, 1056038, 124982, '<td valign="top">A little overblown, but in an artistic kind of way. Definitely makes me want to look for that minute extra!</td>', 'A little overblown, but in an artistic kind of way. Definitely makes me want to look for that minute extra!', '2013-03-04 21:58:48.000000', NULL, 1),
(6991545, 1056442, 81362, '<td valign="top">I suspect the brownish color will decrease the scores. I''ll be interested in any description of how this was made.</td>', 'I suspect the brownish color will decrease the scores. I''ll be interested in any description of how this was made.', '2013-03-04 21:58:55.000000', NULL, 1),
(6991548, 1056332, 81362, '<td valign="top">Reminds me of a scientific botanial print, good detail in the two main flowers. Good studio lighting although with slight darkening of background toward the bottom of the image. Should score well ahead of most of the darker grey images in the competition.</td>', 'Reminds me of a scientific botanial print, good detail in the two main flowers. Good studio lighting although with slight darkening of background toward the bottom of the image. Should score well ahead of most of the darker grey images in the competition.', '2013-03-04 22:02:53.000000', NULL, 1),
(6991551, 1056446, 81362, '<td valign="top">Cute expression and good background (limited by minimal edit rules). Should be one of the higher scoring entries.</td>', 'Cute expression and good background (limited by minimal edit rules). Should be one of the higher scoring entries.', '2013-03-04 22:03:58.000000', NULL, 1),
(6991553, 1056402, 81362, '<td valign="top">Nice collection of simple to complex shapes.</td>', 'Nice collection of simple to complex shapes.', '2013-03-04 22:05:50.000000', NULL, 1),
(6991554, 1056176, 81362, '<td valign="top">Background texture adds interest.</td>', 'Background texture adds interest.', '2013-03-04 22:06:33.000000', NULL, 1),
(6991559, 1056381, 81362, '<td valign="top">Nice portrait and good white background. Suspect face with dark hair will not be considered "light" by some voters.</td>', 'Nice portrait and good white background. Suspect face with dark hair will not be considered "light" by some voters.', '2013-03-04 22:08:25.000000', NULL, 1),
(6991561, 1056435, 81362, '<td valign="top">Delicate and artful. Background is nice - light with variation. Foreground subjects read as dark rather than light, which probably will hurt scores.</td>', 'Delicate and artful. Background is nice - light with variation. Foreground subjects read as dark rather than light, which probably will hurt scores.', '2013-03-04 22:09:29.000000', NULL, 1),
(6991563, 1055186, 81362, '<td valign="top">Meets challenge topic and displays skill with lighting. Color in petals makes a more interesting image.</td>', 'Meets challenge topic and displays skill with lighting. Color in petals makes a more interesting image.', '2013-03-04 22:10:39.000000', NULL, 1),
(6991565, 1056323, 81362, '<td valign="top">I lkie that we can still see texture in the white wall. Nice still life.</td>', 'I lkie that we can still see texture in the white wall. Nice still life.', '2013-03-04 22:11:31.000000', NULL, 1),
(6991566, 1055227, 81362, '<td valign="top">Delicate flower with good symmetry. The pink color cast will hurt the scores.</td>', 'Delicate flower with good symmetry. The pink color cast will hurt the scores.', '2013-03-04 22:12:15.000000', NULL, 1),
(6991567, 1056259, 81362, '<td valign="top">Good detail in the feathers and eye. Background is pretty far from white, so this may not do so well in this challenge as it might in a free study.</td>', 'Good detail in the feathers and eye. Background is pretty far from white, so this may not do so well in this challenge as it might in a free study.', '2013-03-04 22:13:58.000000', NULL, 1),
(6991572, 1055273, 81362, '<td valign="top">Interesting flowers. Brighter exposure  would help get this closer to the challenge criteria.</td>', 'Interesting flowers. Brighter exposure  would help get this closer to the challenge criteria.', '2013-03-04 22:17:36.000000', NULL, 1),
(6991578, 1056071, 81362, '<td valign="top">Peaceful portriat with high key background that should score in upper half of entries. Dark hair and dark red pattern probably deviate enough from "light" to reduce score from the upper range.</td>', 'Peaceful portriat with high key background that should score in upper half of entries. Dark hair and dark red pattern probably deviate enough from "light" to reduce score from the upper range.', '2013-03-04 22:21:04.000000', NULL, 1),
(6991579, 1056038, 81362, '<td valign="top">On my calibrated monitor, a number of the petals merge into the background. Shading the petals a little from the main light might have improved definition of the details.</td>', 'On my calibrated monitor, a number of the petals merge into the background. Shading the petals a little from the main light might have improved definition of the details.', '2013-03-04 22:22:28.000000', NULL, 1),
(6991582, 1056310, 81362, '<td valign="top">Nicely done, with preservation of subject/background separation, at least when viewed with a calibrated monitor.</td>', 'Nicely done, with preservation of subject/background separation, at least when viewed with a calibrated monitor.', '2013-03-04 22:23:34.000000', NULL, 1),
(6991590, 1056102, 81362, '<td valign="top">Nice smile. Background is white, but the shirt colors and hair tones may not qualify as "light" enough for the challenge. Although the top and bottom white areas set off by cyan lines might be accomplished with paper and string, it gives the apperance of being added in post processing with techniques not allowed in minimal edit rules.</td>', 'Nice smile. Background is white, but the shirt colors and hair tones may not qualify as "light" enough for the challenge. Although the top and bottom white areas set off by cyan lines might be accomplished with paper and string, it gives the apperance of being added in post processing with techniques not allowed in minimal edit rules.', '2013-03-04 22:29:06.000000', NULL, 1),
(6991591, 1056417, 81362, '<td valign="top">I can see this as one of the top three.</td>', 'I can see this as one of the top three.', '2013-03-04 22:29:35.000000', NULL, 1),
(6991592, 1056178, 81362, '<td valign="top">The feather almost becomes smoke in an abstract sort of way.</td>', 'The feather almost becomes smoke in an abstract sort of way.', '2013-03-04 22:30:46.000000', NULL, 1),
(6991594, 1055988, 81362, '<td valign="top">Could be the front of a greeting card. Just add message.</td>', 'Could be the front of a greeting card. Just add message.', '2013-03-04 22:32:43.000000', NULL, 1),
(6991596, 1055176, 81362, '<td valign="top">Intersting geometry, but rather on the dark end of the scale for the challenge.</td>', 'Intersting geometry, but rather on the dark end of the scale for the challenge.', '2013-03-04 22:34:31.000000', NULL, 1),
(6991598, 1056335, 81362, '<td valign="top">I almost did the exact same subject, so appreciate how well this is done.</td>', 'I almost did the exact same subject, so appreciate how well this is done.', '2013-03-04 22:35:54.000000', NULL, 1),
(6991603, 1056257, 81362, '<td valign="top">Backlit curtains make a more interesting white background than the studio white paper backdrop alternative. I can see this as one of the high scoring entries.</td>', 'Backlit curtains make a more interesting white background than the studio white paper backdrop alternative. I can see this as one of the high scoring entries.', '2013-03-04 22:39:15.000000', NULL, 1),
(6991607, 1056440, 81362, '<td valign="top">Good subject choice. However, since camera light meters expect subjects that average to neutral grey, making things look white requires intervention to override what the meter thinks. This image could result from use of one of the automated modes without the corrective intervention. Exposure compensation or manual mode with brighter exposure would have helped.</td>', 'Good subject choice. However, since camera light meters expect subjects that average to neutral grey, making things look white requires intervention to override what the meter thinks. This image could result from use of one of the automated modes without the corrective intervention. Exposure compensation or manual mode with brighter exposure would have helped.', '2013-03-04 22:43:32.000000', NULL, 1),
(6991636, 1056435, 114285, '<td valign="top">dreamy and lovely!</td>', 'dreamy and lovely!', '2013-03-04 23:39:00.000000', NULL, 1),
(6991694, 1056415, 114285, '<td valign="top">How cute is this, already voted~</td>', 'How cute is this, already voted~', '2013-03-05 00:47:22.000000', NULL, 1),
(6991712, 1055186, 126903, '<td valign="top">this is gorgeous..10</td>', 'this is gorgeous..10', '2013-03-05 01:19:47.000000', NULL, 1),
(6991715, 1056289, 126903, '<td valign="top">Beautiful focus.</td>', 'Beautiful focus.', '2013-03-05 01:21:35.000000', NULL, 1),
(6991718, 1056441, 126903, '<td valign="top">cool effect.</td>', 'cool effect.', '2013-03-05 01:28:55.000000', NULL, 1),
(6991737, 1056435, 49109, '<td valign="top">almost the opposite of what was called for - dark subject, light only from the back and not enough to call the background white</td>', 'almost the opposite of what was called for - dark subject, light only from the back and not enough to call the background white', '2013-03-05 02:13:42.000000', NULL, 1),
(6991739, 1055133, 49109, '<td valign="top">good focus but underexposed and wrong white balance</td>', 'good focus but underexposed and wrong white balance', '2013-03-05 02:14:40.000000', NULL, 1),
(6991742, 1055699, 49109, '<td valign="top">good attempt but the composition is rather unpleaseant</td>', 'good attempt but the composition is rather unpleaseant', '2013-03-05 02:15:31.000000', NULL, 1),
(6991744, 1056277, 49109, '<td valign="top">quite good lighting and focus but literally there''s no background, just frame-filling subject</td>', 'quite good lighting and focus but literally there''s no background, just frame-filling subject', '2013-03-05 02:16:57.000000', NULL, 1),
(6991747, 1056400, 49109, '<td valign="top">not a white background for me but the flower looks good</td>', 'not a white background for me but the flower looks good', '2013-03-05 02:19:36.000000', NULL, 1),
(6991749, 1056291, 49109, '<td valign="top">too bad this is not in focus</td>', 'too bad this is not in focus', '2013-03-05 02:20:06.000000', NULL, 1),
