(6991752, 1056189, 49109, '<td valign="top">good focus and nice vibrant yellow; background is too grayish, crop looks a bit random</td>', 'good focus and nice vibrant yellow; background is too grayish, crop looks a bit random', '2013-03-05 02:22:47.000000', NULL, 1),
(6991754, 1056176, 49109, '<td valign="top">good detail - looking at the ton of dust and lint almost too much - comp is rather boring</td>', 'good detail - looking at the ton of dust and lint almost too much - comp is rather boring', '2013-03-05 02:23:52.000000', NULL, 1),
