INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6991757, 1056144, 108580, '<td valign="top">Odd new take on an old style. Very impressive.</td>', 'Odd new take on an old style. Very impressive.', '2013-03-05 02:25:03.000000', NULL, 1),
(6991758, 1056401, 49109, '<td valign="top">nice DOF and good subject choice; however, background is a bit too dark while lights in top flower are blown</td>', 'nice DOF and good subject choice; however, background is a bit too dark while lights in top flower are blown', '2013-03-05 02:26:46.000000', NULL, 1),
(6991759, 1056415, 49109, '<td valign="top">nice shot if it was another challenge - overall too grayish</td>', 'nice shot if it was another challenge - overall too grayish', '2013-03-05 02:27:26.000000', NULL, 1),
(6991760, 1056289, 49109, '<td valign="top">Excellent focus and well composed; One of the best entries, while the light on the cat is great, still the background is a bit too dark</td>', 'Excellent focus and well composed; One of the best entries, while the light on the cat is great, still the background is a bit too dark', '2013-03-05 02:29:12.000000', NULL, 1),
(6991762, 1056335, 49109, '<td valign="top">yes, why not be literal from time to time, subject is not too interesting but overall this is quite well done</td>', 'yes, why not be literal from time to time, subject is not too interesting but overall this is quite well done', '2013-03-05 02:30:24.000000', NULL, 1),
(6991764, 1056304, 49109, '<td valign="top">WB is slightly off but otherwise very well done</td>', 'WB is slightly off but otherwise very well done', '2013-03-05 02:32:41.000000', NULL, 1),
(6991765, 1055186, 49109, '<td valign="top">coming back to bump you up; a bit much "copy space" here but definitely top 5 material. Karen?</td>', 'coming back to bump you up; a bit much "copy space" here but definitely top 5 material. Karen?', '2013-03-05 02:33:52.000000', NULL, 1),
(6991774, 1055678, 81362, '<td valign="top">Fine balance, uniform background, and interesting texture. Bumping up a notch on repeat viewing; although somewhat dark in color, the old brown leaves are light(weight).</td>', 'Fine balance, uniform background, and interesting texture. Bumping up a notch on repeat viewing; although somewhat dark in color, the old brown leaves are light(weight).', '2013-03-05 03:51:36.000000', NULL, 1),
(6991775, 1056441, 81362, '<td valign="top">Science fiction strange. The white fabric sets off the light toned face as a kind of background, although some will deduct points for the distant background being a little darker instead of pure white.</td>', 'Science fiction strange. The white fabric sets off the light toned face as a kind of background, although some will deduct points for the distant background being a little darker instead of pure white.', '2013-03-05 03:54:30.000000', NULL, 1),
(6991776, 1055116, 81362, '<td valign="top">Lovely composition. Having background a bit darker than the subject may hurt overall score.</td>', 'Lovely composition. Having background a bit darker than the subject may hurt overall score.', '2013-03-05 03:56:27.000000', NULL, 1),
(6991778, 1055929, 81362, '<td valign="top">Despite interesting and artistic composition, this suffers from excessive darkness in comparison to entries with white background. For this challenge, brighter exposure would have helped a lot.</td>', 'Despite interesting and artistic composition, this suffers from excessive darkness in comparison to entries with white background. For this challenge, brighter exposure would have helped a lot.', '2013-03-05 04:18:23.000000', NULL, 1),
(6991781, 1055133, 81362, '<td valign="top">Seems underexposed as though shot in automatic exposure mode without using  exposure compesnation to adjust away from middle grey expected by internal meter. Too bad, as flower elements beng sharp in front with shallow depth of field works for this subject.</td>', 'Seems underexposed as though shot in automatic exposure mode without using  exposure compesnation to adjust away from middle grey expected by internal meter. Too bad, as flower elements beng sharp in front with shallow depth of field works for this subject.', '2013-03-05 04:31:10.000000', NULL, 1),
(6991782, 1056357, 81362, '<td valign="top">Exposure of rings, ribbon, and container not bad, although could be a notch or two brighter. But the dark woodgrain main surface drops this way down in comparison to other entries that used "on white" as the concept for the entire background.</td>', 'Exposure of rings, ribbon, and container not bad, although could be a notch or two brighter. But the dark woodgrain main surface drops this way down in comparison to other entries that used "on white" as the concept for the entire background.', '2013-03-05 04:38:25.000000', NULL, 1),
(6991783, 1056436, 81362, '<td valign="top">Elegant simplicity. Exposure could have been slightly brighter, but I still expect to see this in the top 10.</td>', 'Elegant simplicity. Exposure could have been slightly brighter, but I still expect to see this in the top 10.', '2013-03-05 04:39:39.000000', NULL, 1),
(6991784, 1056408, 81362, '<td valign="top">One of my favorites in the challenge. Nicely done.</td>', 'One of my favorites in the challenge. Nicely done.', '2013-03-05 04:40:19.000000', NULL, 1),
(6991787, 1056230, 81362, '<td valign="top">Layers of brown spots and distortion, degree of blur, odd shirt message, and stark setting all are elements that could be an artistic statement. But it doesn''t draw me in even after looking quite a while. Lots of dark elements likely to push score low. Will be interested to hear how this was accomplished in minimal editing (shot thorugh dirty pane of glass?).</td>', 'Layers of brown spots and distortion, degree of blur, odd shirt message, and stark setting all are elements that could be an artistic statement. But it doesn''t draw me in even after looking quite a while. Lots of dark elements likely to push score low. Will be interested to hear how this was accomplished in minimal editing (shot thorugh dirty pane of glass?).', '2013-03-05 04:52:19.000000', NULL, 1),
(6991788, 1056128, 81362, '<td valign="top">Having the door slightly off from straight upright fits the jolting impact of an emotional situation. Sharpness is good. Exposure could have been much brighter for this challenge topic (this much grey suggests that an automtic exposure mode might have been used without enough exposure compensation).</td>', 'Having the door slightly off from straight upright fits the jolting impact of an emotional situation. Sharpness is good. Exposure could have been much brighter for this challenge topic (this much grey suggests that an automtic exposure mode might have been used without enough exposure compensation).', '2013-03-05 04:59:58.000000', NULL, 1),
(6991789, 1056151, 81362, '<td valign="top">Pink color cast hurts this one.</td>', 'Pink color cast hurts this one.', '2013-03-05 05:01:17.000000', NULL, 1),
(6991820, 1056093, 114285, '<td valign="top">Compared to the others, this looks kind of grey, not as white as I would like it, still everything else is fine to me.</td>', 'Compared to the others, this looks kind of grey, not as white as I would like it, still everything else is fine to me.', '2013-03-05 06:11:14.000000', NULL, 1),
(6991824, 1056363, 112828, '<td valign="top">Hello robot face.<br/> <br/>Seriously, I think this is cute, but the photo is washed out and generally badly lit.   Composition is off as well, with a right-leaning tilt.<br/> <br/>Kevin Payne is that you? ;)</td>', 'Hello robot face. Seriously, I think this is cute, but the photo is washed out and generally badly lit.   Composition is off as well, with a right-leaning tilt. Kevin Payne is that you? ;)', '2013-03-05 06:19:48.000000', NULL, 1),
(6991832, 1055062, 153814, '<td valign="top">HA this is great. I was standing on 47th &amp; 6th looking at this building and thinking of the same shot. I had blue bird skies so I didn''t take the shot.<br/>I hope it does well.</td>', 'HA this is great. I was standing on 47th & 6th looking at this building and thinking of the same shot. I had blue bird skies so I didn''t take the shot.I hope it does well.', '2013-03-05 07:39:48.000000', NULL, 1),
